#!/usr/bin/env bash
# Make this machine part of the pool.
#
#   sudo deploy/node.sh server
#       This machine becomes the Kubernetes control plane (K3s) with the web GUI, and also
#       offers its own CPUs/GPUs. Writes deploy/join-device.sh for adding devices.
#
#   sudo bash join-device.sh [device.conf]    (on each device; generated by the step above)
#       Registers the device with the control plane. From then on it re-registers by itself
#       on every boot and its CPUs, memory and GPUs are schedulable.
#
# Pool VPN: if `sudo deploy/vpn.sh init` was run first, the cluster runs over that private
# network. Each device then needs its own settings file from `vpn.sh add <device>`, passed
# as the argument to join-device.sh.
#
# Optional environment: NODE_IP (LAN address to use), NODE_NAME, K3S_VERSION.
set -euo pipefail

# sudo normally provides this; pkexec and bare root shells may not, and K3s installs there.
export PATH=$PATH:/usr/local/bin
MODE=${1:-}
VPN_CONF=${2:-}
VPN_IF=pool0
POD_CIDR=${POOL_POD_CIDR:-10.42.0.0/16}
SERVICE=k3s
if [[ $MODE == agent ]]; then SERVICE=k3s-agent; fi
# Re-running on a machine that is already in the pool reconfigures it in place.
RERUN=false
if systemctl is-active --quiet "$SERVICE" 2>/dev/null; then RERUN=true; fi
log() { printf '\033[1m==> %s\033[0m\n' "$*"; }
die() { echo "error: $*" >&2; exit 1; }

[[ $MODE == server || $MODE == agent ]] || die "usage: sudo $0 server   (or run the generated join-device.sh on a device)"
[[ $EUID -eq 0 ]] || die "must run as root (use sudo)"
command -v curl >/dev/null || die "curl is required"
command -v systemctl >/dev/null || die "systemd is required"
if [[ $MODE == server && -e /etc/systemd/system/k3s-agent.service ]]; then
  die "this machine is already a device in a pool (k3s-agent); run k3s-agent-uninstall.sh first"
fi
if [[ $MODE == agent ]]; then
  [[ ! -e /etc/systemd/system/k3s.service ]] || die "this machine is a control plane; it is already in its own pool"
  [[ -n ${K3S_URL:-} && -n ${K3S_TOKEN:-} ]] || die "K3S_URL and K3S_TOKEN are required (use the generated join-device.sh)"
fi

# ---------------------------------------------------------------- address
# Look only at the main routing table: VPN clients (WireGuard, etc.) put their default route
# in a separate table and would otherwise be picked as "the" interface.
detect_ip() {
  local dev
  dev=$(ip -4 route show default table main | awk '{for (i = 1; i < NF; i++) if ($i == "dev") {print $(i + 1); exit}}')
  [[ -n $dev ]] || return 1
  ip -4 -o addr show dev "$dev" scope global | awk '{split($4, a, "/"); print a[1]; exit}'
}
LAN_IP=$(detect_ip || true)

# ---------------------------------------------------------------- pool VPN
# A device handed its VPN settings connects first, so everything after runs over the VPN.
if [[ $MODE == agent && -n $VPN_CONF ]]; then
  [[ -r $VPN_CONF ]] || die "cannot read VPN settings file $VPN_CONF"
  if ! command -v wg-quick >/dev/null; then
    log "installing wireguard-tools"
    if command -v apt-get >/dev/null; then
      DEBIAN_FRONTEND=noninteractive apt-get install -y wireguard-tools
    elif command -v dnf >/dev/null; then
      dnf install -y wireguard-tools
    else
      die "install wireguard-tools for this distribution, then re-run"
    fi
  fi
  log "connecting to the pool VPN"
  mkdir -p /etc/wireguard
  install -m 600 "$VPN_CONF" "/etc/wireguard/$VPN_IF.conf"
  # Pod traffic goes straight over the VPN, so this device must route the pod range into
  # it (settings files issued before that change do not list it yet).
  if ! grep -q "^AllowedIPs = .*${POD_CIDR//./\\.}" "/etc/wireguard/$VPN_IF.conf"; then
    sed -i "s#^AllowedIPs = \\(.*\\)\$#AllowedIPs = \\1, $POD_CIDR#" "/etc/wireguard/$VPN_IF.conf"
  fi
  systemctl enable "wg-quick@$VPN_IF" >/dev/null
  systemctl restart "wg-quick@$VPN_IF"
fi
USE_VPN=false
if ip link show "$VPN_IF" >/dev/null 2>&1; then
  USE_VPN=true
  VPN_IP=$(ip -4 -o addr show dev "$VPN_IF" | awk '{split($4, a, "/"); print a[1]; exit}')
  [[ -n $VPN_IP ]] || die "the pool VPN interface $VPN_IF has no address"
  NODE_IP=${NODE_IP:-$VPN_IP}
  log "pool VPN is up: using address $NODE_IP"
  if [[ $MODE == agent ]]; then
    hub=${K3S_URL#https://}
    hub=${hub%%:*}
    reached=false
    for _ in 1 2 3 4 5 6; do
      if ping -c 1 -W 3 "$hub" >/dev/null 2>&1; then reached=true; break; fi
    done
    if ! $reached; then
      # Say which half is broken: the path to the control plane, or the VPN on top of it.
      endpoint=$(wg show "$VPN_IF" endpoints | awk '{print $2; exit}')
      host=${endpoint%:*}
      echo "error: the control plane ($hub) does not answer over the pool VPN." >&2
      echo "  this device's addresses: $(ip -4 -o addr show scope global | awk '{print $2 "=" $4}' | paste -sd' ' -)" >&2
      echo "  VPN traffic: $(wg show "$VPN_IF" transfer | awk '{print "received " $2 " bytes, sent " $3 " bytes"}')" >&2
      if ping -c 2 -W 2 "$host" >/dev/null 2>&1; then
        echo "  $host answers ping, but not on UDP port ${endpoint##*:}: a firewall on the control plane is" >&2
        echo "  blocking that port, or this invite is no longer valid there (check: sudo wg show $VPN_IF)." >&2
      else
        echo "  $host does not answer ping either: this device cannot reach the control plane's" >&2
        echo "  address. Put both on the same network, or turn off any other VPN / kill switch here" >&2
        echo "  (or on the control plane) that blocks local-network traffic, then run this again." >&2
      fi
      exit 1
    fi
  fi
elif [[ $MODE == agent && ${POOL_VPN:-0} == 1 ]]; then
  die "this pool runs over its VPN: on the control plane run  sudo deploy/vpn.sh add <device-name>  and pass the resulting .conf file:  sudo bash $0 <device-name>.conf"
else
  NODE_IP=${NODE_IP:-$LAN_IP}
  [[ -n $NODE_IP ]] || die "could not detect this machine's LAN address; set NODE_IP=<address>"
  log "using LAN address $NODE_IP"
fi

# ---------------------------------------------------------------- GPU
HAS_GPU=false
if command -v nvidia-smi >/dev/null && nvidia-smi -L >/dev/null 2>&1; then
  HAS_GPU=true
  log "NVIDIA GPU(s): $(nvidia-smi --query-gpu=name --format=csv,noheader | paste -sd, -)"
  if ! command -v nvidia-container-runtime >/dev/null; then
    log "installing the NVIDIA container toolkit (lets containers use the GPU)"
    export DEBIAN_FRONTEND=noninteractive
    if command -v apt-get >/dev/null; then
      if ! apt-get install -y nvidia-container-toolkit; then
        # Not packaged by this distribution: use NVIDIA's repository.
        curl -fsSL https://nvidia.github.io/libnvidia-container/gpgkey |
          gpg --dearmor --yes -o /usr/share/keyrings/nvidia-container-toolkit-keyring.gpg
        curl -fsSL https://nvidia.github.io/libnvidia-container/stable/deb/nvidia-container-toolkit.list |
          sed 's#deb https://#deb [signed-by=/usr/share/keyrings/nvidia-container-toolkit-keyring.gpg] https://#g' \
            > /etc/apt/sources.list.d/nvidia-container-toolkit.list
        apt-get update
        apt-get install -y nvidia-container-toolkit
      fi
    elif command -v dnf >/dev/null; then
      curl -fsSL https://nvidia.github.io/libnvidia-container/stable/rpm/nvidia-container-toolkit.repo \
        -o /etc/yum.repos.d/nvidia-container-toolkit.repo
      dnf install -y nvidia-container-toolkit
    else
      die "install nvidia-container-toolkit for this distribution, then re-run"
    fi
    command -v nvidia-container-runtime >/dev/null || die "nvidia-container-runtime is still missing after installing the toolkit"
  fi
else
  log "no NVIDIA GPU with a working driver here: joining as a CPU-only device"
fi

# ---------------------------------------------------------------- K3s configuration
mkdir -p /etc/rancher/k3s
{
  echo "node-ip: $NODE_IP"
  if [[ -n ${NODE_NAME:-} ]]; then echo "node-name: $NODE_NAME"; fi
  # Kubelet's defaults evict pods when the disk is under 10% free, which idles a large,
  # mostly-full workstation disk that still has tens of GB available. Use absolute floors.
  echo "kubelet-arg:"
  echo "  - eviction-hard=memory.available<200Mi,nodefs.available<5Gi,imagefs.available<5Gi"
  echo "  - image-gc-high-threshold=97"
  echo "  - image-gc-low-threshold=95"
  echo "node-label:"
  echo "  - dist-alloc/pool=true"
  if $HAS_GPU; then
    echo "  - nvidia.com/gpu.present=true"
    # Containers on this node run under the NVIDIA runtime, so any pod that requests
    # nvidia.com/gpu gets its GPU without extra pod configuration.
    echo "default-runtime: nvidia"
  fi
  if $USE_VPN; then echo "flannel-iface: $VPN_IF"; fi
  if [[ $MODE == server ]]; then
    if $USE_VPN; then
      # The pool VPN already encrypts and carries everything between devices, so pods are
      # simply routed over it (no second tunnel inside the first).
      echo "flannel-backend: host-gw"
    else
      # Encrypt pod traffic between devices with kernel WireGuard.
      echo "flannel-backend: wireguard-native"
    fi
    echo "tls-san:"
    echo "  - $NODE_IP"
    if [[ -n $LAN_IP && $LAN_IP != "$NODE_IP" ]]; then echo "  - $LAN_IP"; fi
  fi
} > /etc/rancher/k3s/config.yaml

# ---------------------------------------------------------------- firewall
if command -v ufw >/dev/null && ufw status | grep -q '^Status: active'; then
  log "opening ufw for cluster traffic"
  ufw allow from 10.42.0.0/16 comment 'k3s pods' >/dev/null
  ufw allow from 10.43.0.0/16 comment 'k3s services' >/dev/null
  ufw allow 51820/udp comment 'k3s wireguard' >/dev/null
  ufw allow 10250/tcp comment 'k3s kubelet' >/dev/null
  if $USE_VPN; then ufw allow in on "$VPN_IF" comment 'pool vpn members' >/dev/null; fi
  if [[ $MODE == server ]]; then
    ufw allow 6443/tcp comment 'k3s api' >/dev/null
    ufw allow 443/tcp comment 'cluster gui' >/dev/null
  fi
elif command -v firewall-cmd >/dev/null && firewall-cmd --state >/dev/null 2>&1; then
  log "opening firewalld for cluster traffic"
  firewall-cmd --permanent --zone=trusted --add-source=10.42.0.0/16 --add-source=10.43.0.0/16 >/dev/null
  firewall-cmd --permanent --add-port=51820/udp --add-port=10250/tcp >/dev/null
  if $USE_VPN; then firewall-cmd --permanent --zone=trusted --add-interface="$VPN_IF" >/dev/null; fi
  if [[ $MODE == server ]]; then firewall-cmd --permanent --add-port=6443/tcp --add-port=443/tcp >/dev/null; fi
  firewall-cmd --reload >/dev/null
fi

# ---------------------------------------------------------------- install
# The installer only restarts K3s when its own files changed, not when ours did.
apply_changes() {
  $RERUN || return 0
  log "restarting $SERVICE to apply the new settings"
  # A tunnel device left over from an earlier network mode would keep its stale routes.
  ip link delete flannel.1 2>/dev/null || true
  systemctl restart "$SERVICE"
}

if [[ $MODE == agent ]]; then
  log "joining the pool at $K3S_URL"
  curl -sfL https://get.k3s.io |
    INSTALL_K3S_VERSION=${K3S_VERSION:-} K3S_URL=$K3S_URL K3S_TOKEN=$K3S_TOKEN sh -s - agent
  apply_changes
  log "done: this device registers itself on every boot (service: k3s-agent)"
  echo "    check from the control plane:  kubectl get nodes"
  echo "    leave the pool:                sudo k3s-agent-uninstall.sh"
  exit 0
fi

log "installing the control plane"
curl -sfL https://get.k3s.io | INSTALL_K3S_VERSION=${K3S_VERSION:-} sh -s - server
apply_changes
K="k3s kubectl"

wait_for() { # wait_for <seconds> <description> <command...>
  local deadline=$((SECONDS + $1)) what=$2
  shift 2
  until "$@" >/dev/null 2>&1; do
    if ((SECONDS > deadline)); then return 1; fi
    sleep 3
  done
}
wait_for 180 api $K get --raw /readyz || die "the Kubernetes API did not come up; see: journalctl -u k3s"

# K3s applies everything in this directory and keeps it applied. It creates the directory
# itself only some time after the API answers, so make sure it is there.
HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
mkdir -p /var/lib/rancher/k3s/server/manifests
for manifest in "$HERE"/manifests/*.yaml; do
  install -m 600 "$manifest" "/var/lib/rancher/k3s/server/manifests/dist-alloc-$(basename "$manifest")"
done

log "waiting for the GUI to start (first run downloads images)"
GUI_READY=true
wait_for 300 gui $K -n headlamp rollout status deployment/headlamp --timeout=5s || GUI_READY=false
wait_for 60 token $K -n headlamp get secret headlamp-admin-token -o jsonpath='{.data.token}' || true
GUI_TOKEN=$($K -n headlamp get secret headlamp-admin-token -o jsonpath='{.data.token}' 2>/dev/null | base64 -d || true)

# kubectl for the person who ran this.
KUBECONFIG_NOTE=""
if [[ -n ${SUDO_USER:-} && $SUDO_USER != root ]]; then
  USER_HOME=$(getent passwd "$SUDO_USER" | cut -d: -f6)
  mkdir -p "$USER_HOME/.kube"
  TARGET=$USER_HOME/.kube/config
  if [[ -e $TARGET ]] && ! grep -q "https://$NODE_IP:6443" "$TARGET"; then
    TARGET=$USER_HOME/.kube/dist-alloc.yaml   # an unrelated ~/.kube/config is left alone
  fi
  # K3s's bundled kubectl ignores ~/.kube/config unless told to use it.
  KUBECONFIG_NOTE="export KUBECONFIG=$TARGET   # add this line to ~/.bashrc"
  sed "s#https://127.0.0.1:6443#https://$NODE_IP:6443#" /etc/rancher/k3s/k3s.yaml > "$TARGET"
  chmod 600 "$TARGET"
  chown -R "$SUDO_USER" "$USER_HOME/.kube"
fi

# One self-contained file that joins a device: this script with the address and secret baked in.
JOIN=$HERE/join-device.sh
{
  echo '#!/usr/bin/env bash'
  echo "# Generated by node.sh on $(date -I). Contains the pool's join secret: do not commit or share."
  printf 'export K3S_URL=%q K3S_TOKEN=%q K3S_VERSION=%q POOL_VPN=%q\n' \
    "https://$NODE_IP:6443" "$(cat /var/lib/rancher/k3s/server/node-token)" \
    "$(k3s --version | awk 'NR == 1 {print $3}')" "$(if $USE_VPN; then echo 1; else echo 0; fi)"
  echo 'set -- agent "$@"'
  tail -n +2 "${BASH_SOURCE[0]}"
} > "$JOIN"
chmod 700 "$JOIN"
if [[ -n ${SUDO_USER:-} ]]; then chown "$SUDO_USER" "$JOIN"; fi

echo
log "control plane is up"
$K get nodes -o custom-columns='NODE:.metadata.name,CPU:.status.allocatable.cpu,MEMORY:.status.allocatable.memory,GPU:.status.allocatable.nvidia\.com/gpu'
echo
GUI_IP=${LAN_IP:-$NODE_IP}
# The login token is an admin secret: it goes to a private file, not the terminal or logs.
INFO=$HERE/pool-info.txt
(
  umask 077
  {
    echo "GUI      https://$GUI_IP/"
    echo "login    paste this token:"
    echo
    echo "$GUI_TOKEN"
  } > "$INFO"
)
if [[ -n ${SUDO_USER:-} ]]; then chown "$SUDO_USER" "$INFO"; fi
if $GUI_READY; then
  echo "GUI      https://$GUI_IP/   (self-signed certificate: accept the browser warning)"
else
  echo "GUI      https://$GUI_IP/   (still starting; check: kubectl -n headlamp get pods)"
fi
if [[ -n $GUI_TOKEN ]]; then
  echo "login    with the token saved in $INFO"
else
  echo "login    token not issued yet; later: kubectl -n headlamp get secret headlamp-admin-token -o jsonpath='{.data.token}' | base64 -d"
fi
if [[ -n $KUBECONFIG_NOTE ]]; then echo "kubectl  $KUBECONFIG_NOTE"; fi
echo "add a device (Linux, with ssh access):"
if $USE_VPN; then
  echo "    sudo $HERE/vpn.sh add <device-name>        # creates $HERE/vpn/<device-name>.conf"
  echo "    scp $JOIN $HERE/vpn/<device-name>.conf <user>@<device>:"
  echo "    ssh -t <user>@<device> sudo bash join-device.sh <device-name>.conf"
else
  echo "    scp $JOIN <user>@<device>:  &&  ssh -t <user>@<device> sudo bash join-device.sh"
fi
echo "remove everything from this machine:  sudo k3s-uninstall.sh"
